-- 默认目录独立于管理员当前配置；不覆盖已有自定义目录。
ALTER TABLE design_prompt_template_catalogs ADD COLUMN revision integer NOT NULL DEFAULT 1;
CREATE TABLE design_prompt_template_defaults (
  design_mode text PRIMARY KEY REFERENCES design_prompt_template_catalogs(design_mode),
  version text NOT NULL,
  categories jsonb NOT NULL
);
CREATE TABLE design_prompt_template_versions (
  design_mode text NOT NULL REFERENCES design_prompt_template_catalogs(design_mode),
  revision integer NOT NULL,
  categories jsonb NOT NULL,
  updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  reason text NOT NULL DEFAULT 'save',
  PRIMARY KEY (design_mode, revision)
);
INSERT INTO design_prompt_template_versions (design_mode, revision, categories, updated_by, updated_at, reason)
SELECT design_mode, revision, categories, updated_by, updated_at, 'baseline' FROM design_prompt_template_catalogs;
