INSERT INTO design_prompt_template_defaults (design_mode, version, categories) VALUES ('cabin', '2026-09-10.1', '[{"id": "cabin-type", "name": "客室类型", "options": [{"id": "cabin-metro", "label": "地铁客室", "value": "现代地铁客室"}, {"id": "cabin-high-speed", "label": "高铁客室", "value": "高速铁路客室"}, {"id": "cabin-sleeper", "label": "卧铺客室", "value": "长途卧铺客室"}], "section": "subject", "selection": "single"}, {"id": "camera-angle", "name": "画面角度", "options": [{"id": "camera-center", "label": "中央通道", "value": "中央通道平视视角"}, {"id": "camera-wide", "label": "广角", "value": "客室广角透视"}, {"id": "camera-corner", "label": "角落视角", "value": "客室角落斜向视角"}], "section": "camera", "selection": "single"}, {"id": "component-color", "name": "部件颜色", "options": [{"id": "component-color-red", "label": "红色", "value": "部件采用红色"}, {"id": "component-color-blue", "label": "蓝色", "value": "部件采用蓝色"}, {"id": "component-color-neutral", "label": "中性色", "value": "部件采用低饱和中性色"}], "section": "appearance", "selection": "single"}, {"id": "material", "name": "材质", "options": [{"id": "material-fabric", "label": "织物", "value": "耐磨织物材质"}, {"id": "material-leather", "label": "皮革", "value": "皮革包覆材质"}, {"id": "material-metal", "label": "金属", "value": "拉丝金属材质"}, {"id": "material-composite", "label": "复合材料", "value": "轻量化复合材料"}], "section": "appearance", "selection": "single"}, {"id": "design-style", "name": "设计风格", "options": [{"id": "style-minimal", "label": "现代简约", "value": "现代简约客室风格"}, {"id": "style-technology", "label": "科技感", "value": "未来科技感客室风格"}, {"id": "style-warm", "label": "温暖舒适", "value": "温暖舒适客室风格"}], "section": "style", "selection": "single"}, {"id": "image-size", "name": "图像尺寸", "options": [{"id": "size-square", "label": "方形", "value": "方形构图，1024×1024", "width": 1024, "height": 1024}, {"id": "size-landscape", "label": "横向", "value": "横向构图，2048×1080", "width": 2048, "height": 1080}, {"id": "size-panorama", "label": "全景", "value": "超宽幅全景构图，2560×1080", "width": 2560, "height": 1080}], "section": "parameters", "selection": "si